<?php $layout='layouts.app'; ?>
<div style="display:flex;justify-content:space-between;align-items:center"><div><h1>Notifications</h1><p class="muted"><?= (int)$unread ?> unread notification(s).</p></div><a class="btn btn-outline" href="/student-portal">Dashboard</a></div>
<div class="card" style="margin-top:var(--space-4)"><div class="card-body"><table class="table"><thead><tr><th>Title</th><th>Type</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($messages as $message): ?><tr><td><?= e($message['title']) ?><br><small><?= e((string)$message['body']) ?></small></td><td><?= e(ucfirst((string)$message['type'])) ?></td><td><?= e((string)$message['published_at']) ?></td><td><?= empty($message['read_at'])?'Unread':'Read' ?></td><td><?php if(empty($message['read_at'])): ?><form method="post" action="/student-portal/notifications/<?= (int)$message['id'] ?>/read"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><button class="btn btn-outline" type="submit">Mark read</button></form><?php endif; ?></td></tr><?php endforeach; if(!$messages): ?><tr><td colspan="5">No notifications yet.</td></tr><?php endif; ?></tbody></table></div></div>
